 mount(){document.body.classList.add('bridge-active');this.host.innerHTML=`<section class="bridge-workshop" dir="rtl"><div class="bridge-heading"><div><small>عملیات خیبر / فصل سوم / کارگاه ۱۳۶۲</small><h1>طراحی و ساخت نمونه پل خیبر</h1></div><div><button data-b="wide">نمای افقی</button><button data-b="sound" aria-pressed="false">صدا: خاموش</button><button data-b="resetKit">بازگشت همه مصالح</button><button data-b="help">راهنما</button><button data-b="export">خروجی ذخیره</button><button data-b="import">ورود ذخیره</button><button data-b="exit">بازگشت به قرارگاه</button></div></div><nav class="bridge-steps" aria-label="مراحل ساخت"></nav><div class="bridge-workspace"><div class="bridge-table"><div class="bridge-crew"><div>${GameArt.portrait('player','front')}</div><span>میز ماکت هور <small>مدل آموزشی، بدون مقیاس واقعی</small></span><div>${GameArt.portrait('mentor')}</div></div><canvas id="bridgeCanvas" aria-label="ماکت تعاملی پل خیبر؛ سطحه‌ها را از انبار بکشید" tabindex="0"></canvas><div id="bridgeMessage" role="status" aria-live="polite"></div></div><aside class="bridge-inspector"></aside></div><div class="bridge-inventory"></div><div class="bridge-bottom"><div class="bridge-camera"><button data-b="zoomIn" aria-label="بزرگ‌نمایی میز">＋</button><button data-b="zoomOut" aria-label="نمای کامل میز">−</button><button data-b="panLeft" aria-label="دیدن سمت چپ میز">←</button><button data-b="panRight" aria-label="دیدن سمت راست میز">→</button></div><small id="bridgeSave"></small><small>گوشی را افقی بگیر · شبیه‌سازی آموزشی</small><button data-b="next" class="primary"></button></div><dialog id="bridgeDialog"></dialog></section>`;
 this.canvas=this.host.querySelector('canvas');this.renderer=new BridgeRenderer(this.canvas);const opt={signal:this.abort.signal};this.host.addEventListener('click',e=>this.click(e),opt);this.host.addEventListener('input',e=>this.input(e),opt);this.host.addEventListener('pointerdown',e=>this.down(e),opt);window.addEventListener('pointermove',e=>this.move(e),opt);window.addEventListener('pointerup',e=>{if(this.drag)this.tapSound();this.up(e)},opt);window.addEventListener('pointercancel',()=>{this.drag=null;this.ui.ghost=null},opt);this.canvas.addEventListener('keydown',e=>{if(e.key==='r'||e.key==='R'){this.rotate(30);e.preventDefault()}},opt);this.refresh();this.save()}
 frame(time){if(!this.host.isConnected)return;this.renderer.draw(this.state,this.ui,time);if(this.ui.testing&&time-this.ui.testStart>=6500){this.ui.testing=false;this.ui.showResult=true;if(this.ui.result.passed){this.state.stage='success';this.message('نمونه اولیه پل خیبر تکمیل شد.');this.save();this.refresh();this.showEnding()}else{this.ui.errors=this.ui.result.errors;this.refresh();this.message('آزمایش ایراد پیدا کرد؛ روی گزارش کنار میز بزن و همان بخش را اصلاح کن.')}}this.raf=requestAnimationFrame(this.frame)}
